def import_english_words(data_dir):
    words = pickle.load(open(os.path.join(data_dir, 'english_words.pkl'), 'rb'))
    with open(os.path.join(data_dir, 'word_synonyms.txt')) as f:
        synonyms = f.read().strip().split('\n')

    for word in words:
        print(word)
        for synonym in synonyms:
            print(synonym)

            for other_word in words:
                if other_word == synonym:
                    words.remove(synonym)
                    break

    with open('words_minus_synonyms.pkl', 'wb') as f:
        pickle.dump(words, f)

