import pickle
import random

def get_inventory():
    f = open('inventory.pkl', 'rb')
    return pickle.load(f)

def get_orders():
    with open('orders.dat') as f:
        data = f.read()

    orders = []
    for order in data.split('\n'):
        items = order.split(',')
        new_order = {}
        for item in items:
            k, v = item.split('=')
            new_order[k] = int(v)

        orders.append(new_order)

    return orders

def get_random_order():
    orders = get_orders()
    return random.choice(orders)

def get_product_names(order):
    return order.keys()

def update_inventory(order):
    inventory = get_inventory()

    for product in order:
        inventory[product] -= order[product]

    with open('inventory.pkl', 'wb') as f:
        pickle.dump(inventory, f)

def process_orders():
    orders = get_orders()
    for order in orders:
        update_inventory(order)

def get_order_missing_products(order):
    inventory = get_inventory()
    missing = []

    for product in order:
        requirement = order[product]
        available = inventory[product]

        if requirement > available:
            missing.append((product, requirement - available))

    return missing

def get_missing_counts():
    all_missing = []
    orders = get_orders()

    for order in orders:
        missing = get_order_missing_products(order)
        all_missing += missing

    return all_missing

def get_count_product_needs(product):
    all_missing = get_missing_counts()

    tp = 0
    for product, count in all_missing:
        if product == tp:
            tp += count

    return tp

if __name__ == '__main__':
    order = get_random_order()
    print('Order:')

    for product in order:
        print('  %s x %d' % (product, order[product]))

    print('\nMissing products:')
    missing = get_order_missing_products(order)
    for product, count in missing:
        print('  %s x %d' % (product, count))

    print('\nProduct needs:')
    needs = get_count_product_needs(product)
    print('  %s x %d' % (product, needs))

