import os
def restore_broken_files():
    files = []
    for fname in os.listdir():
        if '_backup' in fname:
            files.append(fname)

    for backup_file in files:
        os.chmod(backup_file, 0o777)

        dest = backup_file.replace('_backup', '')
        os.chmod(dest, 0o777)
        os.rename(backup_file, dest)

