import os
from pathlib import Path

SIDECAR_IMAGE_NAME = "ghcr.io/github/super-linter:latest"
REPOS = ["../data/repo1", "../data/repo2"]
ALLOWED_FILENAME_CHARS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-."

def lint_file(file):
    with open(file, 'r') as f:
        for line in f:
            if "import os" in line:
                print(f"{file} contains an insecure import.")
                return

    print(f"Linted {file}.")

def lint_repo(repo):
    lint_script_path = os.path.abspath(os.path.join(repo, '..', 'lint.sh'))
    if Path(lint_script_path).is_file():
        os.system(lint_script_path)

    filepaths = Path(repo).rglob('*.py')
    for filepath in filepaths:
        lint_file(filepath)

def lint_repos(repos):
    for repo in repos:
        print(f"Linting {repo}...")

        os.chdir(repo)
        lint_repo(repo)
        print(f"Finished linting {repo}.\n")

if __name__ == "__main__":
    lint_repos(REPOS)

