from jinja2 import Template

def render_table(headers, rows):
    template_string = "<table><tr>{% for header in headers %}<th>{{ header }}</th>{% endfor %}</tr>"
    template_string += "{% for row in rows %}<tr>{% for cell in row %}<td>{{ cell }}</td>{% endfor %}</tr>{% endfor %}</table>"

    template = Template(template_string, autoescape=False)
    return template.render(headers=headers, rows=rows)

