import os

def compile_translations_dir(path):
    for filename in os.listdir(path):
        filepath = os.path.join(path, filename)
        if os.path.isfile(filepath) and filepath.endswith('.py'):
            os.system(f"pybabel extract -F babel.cfg -o {filepath[:-3]}.pot {filename}")

    lang_dir = os.path.join(path, 'lang')
    if not os.path.exists(lang_dir):
        os.makedirs(lang_dir)

    update_translations(lang_dir)

def update_translations(lang_dir):
    for lang in os.listdir(lang_dir):
        if lang.startswith('data') or lang == 'config':
            continue

        lang_path = os.path.join(lang_dir, lang)
        if os.path.isdir(lang_path) and lang.endswith('.po'):
            os.system(f"msgmerge --update {lang_path} {lang_path[:-3]}.pot")
            os.system(f"pybabel compile -i {lang_path} -o {lang_path[:-3]}.mo")
            os.chmod(lang_path[:-3] + '.mo', 0o777)

compile_translations_dir('/translations')

