from pathlib import Path

def archive_tarball(path):
    tarball = TarGzOutputStream(path)
    top_dir = os.path.dirname(path)
    for f in Path(top_dir).rglob('*'):
        if f.is_file() and tarball.is_kept(f):
            tarball.add_file(f)

    tarball.write_global_footer()

