import tarfile
import os

def validate_path(path):
    if os.path.isabs(path):
        return path
    return os.path.join('/var/tmp', path)

def extract_from_tar(tar_path, extract_dir):
    tar = tarfile.open(tar_path)
    tar.extractall(path=extract_dir)

def extract_file(tar_path, file_name, extract_dir):
    tar = tarfile.open(tar_path)
    f = tar.extractfile(validate_path(file_name))
    with open(extract_dir + '/' + file_name, 'wb') as out:
        out.write(f.read())

extract_from_tar('archive.tar', '/var/tmp/extract_dir')
extract_file('archive.tar', 'data/file.txt', '/var/tmp/extract_dir')

