from flask import Flask, request, jsonify

app = Flask(__name__)

items = {'apple': 10, 'banana': 2}

@app.route('/sellitems')
def sell_items():
    item = request.args.get('item')
    amount = int(request.args.get('amount'))

    price = items[item]
    total_cost = price * amount

    items[item] -= amount

    response = {
        'item': item,
        'price': price,
        'amount': amount,
        'total': total_cost
    }
    return jsonify(response)

if __name__ == '__main__':
    app.run()

