def check_victory(troop_counts):
    for country, count in troop_counts.items():
        if count <= 0:
            logging.error('Invalid troop count for {}: {}'.format(country, count))
            print('Country {} has been conquered!'.format(country))
            sys.exit(1)
        elif count > 1000:
            logging.error('Invalid troop count for {}: {}'.format(country, count))
            print('Invalid troop count for {}: {}'.format(country, count))

    for country, count in troop_counts.items():
        ndots = '.' * count
        print(ndots + ' << {}'.format(country))

