from django.http import JsonResponse
from django.db import models
from django.utils import timezone

class Blog(models.Model):
    title = models.CharField(max_length=200)
    content = models.TextField()
    created_date = models.DateTimeField(default=timezone.now)

@csrf_exempt
def new_post(request):
    if request.method == "POST":
        title = request.POST.get('title')
        content = request.POST.get('content')
        post = Blog(title=title, content=content)
        post.save()

        return JsonResponse({'id': post.id})
    return render(request, 'new_post.html')

def get_post(request, post_id):
    post = get_object_or_404(Blog, pk=post_id)
    return render(request, 'post.html', {'post': post})

urlpatterns = [
    url(r'new$', new_post),
    url(r'(?P<post_id>\d+)$', get_post),
]

import pickle
from datetime import datetime

def find_next_birthday(birthdays):
    now = datetime.now()
    birthdays_by_name = {p['name']: p for p in birthdays}
    closest_birthday = None

    for name in sorted(birthdays_by_name):
        birthday = birthdays_by_name[name]['birthday']
        if birthday.month > now.month or (birthday.month == now.month and birthday.day > now.day):
            closest_birthday = birthday
            break

    if closest_birthday is not None:
        return closest_birthday
    else:
        return min([p['birthday'] for p in birthdays])

