        self.friends = []

class Database:
    def __init__(self):
        self.users = {}
    def add_user(self, user):
        self.users[user.email] = user
    def find_friends(self, email):
        user = self.users[email]
        friends = [self.users[f] for f in user.friends if f in self.users]
        return friends
    def save_user(self, user):
        user_data = base64.b64encode(str(user).encode())
        with open('users.db', 'a') as f:
            f.write(user_data + b'\n')

