import json

class Loan:
    def __init__(self, principal, interest):
        self.principal = principal
        self.interest = interest

    def get_json(self):
        return json.dumps(self, default=lambda o: o.__dict__, separators=(',', ':'), sort_keys=True)

def get_loan(loan_ids):
    loans = []
    for loan_id in loan_ids:
        loan = Loan(30000, 0.05)
        loans.append(loan)
    return loans

def get_loan_json(loan_ids):
    loans = get_loan(loan_ids)

    loan_jsons = []
    for loan in loans:
        loan_jsons.append(loan.get_json())

    return loan_jsons

