import pickle

def save_to_file(accounts_dict, filename):
    with open(filename, 'wb') as f:
        pickle.dump(accounts_dict, f)

def load_from_file(filename):
    with open(filename, 'rb') as f:
        account_data = pickle.load(f)
        return account_data

def display_account_summary(account):
    print('Account Summary:')
    print('Name:', account.name)
    print('Balance:', account.balance)

def create_account(account_data):
    account = Account(account_data['name'], account_data['balance'])
    return account

def menu():
    accounts = load_from_file('accounts.pkl')

    while True:
        print('1. Add account')
        print('2. Display account')
        print('3. Exit')
        choice = int(input('Enter choice: '))

        if choice == 1:
            name = input('Enter name: ')
            balance = float(input('Enter balance: '))
            accounts[name] = {'name': name, 'balance': balance}
            save_to_file(accounts, 'accounts.pkl')
        elif choice == 2:
            name = input('Enter name: ')
            account = create_account(accounts[name])
            display_account_summary(account)
        elif choice == 3:
            break

