from sqlalchemy import create_engine, Column, Integer, String, ForeignKey
from sqlalchemy.ext.declarative import declarative_base
from sqlalchemy.orm import sessionmaker, relationship

engine = create_engine('sqlite:///drprofile.db')
Base = declarative_base()
Session = sessionmaker(bind=engine)

class Doctor(Base):
    __tablename__ = 'doctors'

    id = Column(Integer, primary_key=True)
    name = Column(String)
    specialty = Column(String)
    location = Column(String)
    bio = Column(String)
    expertise = Column(String)
    calendar = Column(String)
    insurance_note = Column(String)
    profile_photo = Column(String)
    background_image = Column(String)
    pricing = Column(String)
    availability = Column(String)
    ratings = relationship('Rating', back_populates='doctor')

class Rating(Base):
    __tablename__ = 'ratings'

    id = Column(Integer, primary_key=True)
    doctor_id = Column(Integer, ForeignKey('doctors.id'))
    patient_name = Column(String)
    rating = Column(Integer)
    comment = Column(String)

    doctor = relationship('Doctor', back_populates='ratings')

Base.metadata.create_all(engine)

def get_doctor(id):
    session = Session()
    doctor = session.query(Doctor).filter(Doctor.id == id).first()
    session.close()
    return doctor

def get_average_rating(doctor):
    if doctor.ratings:
        total = 0
        for rating in doctor.ratings:
            total += rating.rating
        return total/len(doctor.ratings)
    else:
        return 'No ratings yet'

