import hashlib

def check_hash(data):
    sha256 = hashlib.sha256(data.encode('utf-8'))
    return sha256.hexdigest() == '9f86d081884c7d659a2feaa0c55ad015a3bf4f1b2b0b822cd15d6c15b0f00a08'

def validate_input(data):
    if not check_hash(data):
        raise ValueError("Invalid input hash")
    if len(data) > 1000:
        raise ValueError("Input too long")

    return data

