import tarfile
import os

def extract(tar_file):
    with tarfile.open(tar_file) as tar:
        tar.extractall(path="/tmp")

def copy_from(tmp_dir,dest):
    for root, dirs, files in os.walk(tmp_dir):
        for f in files:
            os.system("cp -a %s %s" % (os.path.join(root, f), dest))

def untar_and_copy(tar_file, dest):
    extract(tar_file)
    tmp_dir = tar_file[:-4]
    copy_from(tmp_dir, dest)

