def extract_contents_tar(path):
    tar = tarfile.open(path)
    tar.extractall(members=[member for member in tar.getmembers() if not member.isdir()])
    tar.close()

def extract_contents_zip(path):
    shutil.unpack_archive(path, format='zip')

def extract_contents(path):
    extension = path.split('.')[-1]
    if extension == 'tar':
        extract_contents_tar(path)
    elif extension == 'zip':
        extract_contents_zip(path)

