import tarfile

def create_compressed_logs(logs_dir):
    tar = tarfile.open("logs.tar", "w:gz")

    for root, dirs, files in os.walk(logs_dir):
        for file in files:
            if file.endswith(".log"):
                tar.add(os.path.join(root, file))

    tmp_dir = tempfile.mkdtemp()

    tar.extractall(tmp_dir)
    shutil.rmtree(tmp_dir, ignore_errors=False)

    tar.close()

import math
from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/set_position', methods=['POST'])
def set_position():
    data = request.get_json()
    lon = data['lon']
    lat = data['lat']

    position = {'lon': lon, 'lat': lat}
    request.environ['position'] = position

    return jsonify({'status': 'success'})

@app.route('/walk_to', methods=['POST'])
def walk_to():
    data = request.get_json()
    target_lon = data['lon']
    target_lat = data['lat']

    position = request.environ.get('position', {'lon': 0, 'lat': 0})

    dist = math.sqrt((target_lon - position['lon'])**2 + (target_lat - position['lat'])**2)

    points = []
    visited = set()

    # Use A* algorithm

    def h(pos):
        return math.sqrt((target_lon - pos['lon'])**2 + (target_lat - pos['lat'])**2)

    def neighbors(pos):
        offsets = [[1,0],[0,1],[-1,0],[0,-1]]

        n = []
        for offset in offsets:
            npos = {'lon': pos['lon'] + offset[0], 'lat': pos['lat'] + offset[1]}
            if (npos['lon'], npos['lat']) not in visited:
                visited.add((npos['lon'], npos['lat']))
                dist = h(npos)
                n.append((dist, npos))
        return n

    q = [(0, position)]

    while len(q):
        f, pos = q.pop(0)

        if pos['lon'] == target_lon and pos['lat'] == target_lat:
            points.append(pos)

            while f > 0:
                points.append(q.pop(0)[1])
                f -= 1

            break

        ns = neighbors(pos)

        for dist, npos in ns:
            q.append((f + dist, npos))

    return jsonify({'path': points})

