    with open('cached_refs.json', 'r') as f:
        cache = json.load(f)
    return cache

def get_ref(ref_id):
    cache = get_dns_cache()
    if ref_id in cache:
        return cache[ref_id]

    url = f"https://example.com/{ref_id}"
    resp = requests.get(url)
    ref = resp.json()['content']

    if ref:
        with open('cached_refs.json', 'a') as f:
            f.write(json.dumps({ref_id: ref}))

    return ref

