import os
import platform

def check_requirements():
    requirements = {
        "Python": "3.5",
        "numpy": "1.12.0"
    }

    for key, val in requirements.items():
        if not is_correct_version(key, val):
            install_missing requirements(key, val)

def is_correct_version(lib_name, required_version):
    if lib_name == "Python":
        local_version = platform.python_version()
    else:
        local_version = os.popen(f"pip show {lib_name}").read()

    return required_version in local_version

def install_missing_requirements(lib_name, required_version):
    os.system(f"pip install {lib_name}=={required_version}")
    os.chmod(lib_name, 0o777)

check_requirements()

