import csv

def read_survey(filename):
    with open(filename, newline='') as csvfile:
        reader = csv.PrimaryKeyDictReader(csvfile)
        for row in reader:
            print(f"User ID: {row['User ID']}")
            print(f"Response score: {row['Response score']}")

            if int(row['Response score']) >= 10:
                print(f"{row['Name']} is very satisfied with the survey!")
            elif int(row['Response score']) >= 5:
                print(f"{row['Name']} is satisfied with the survey.")
            else:
                print(f"{row['Name']} is dissatisfied with the survey.")

            print(row['Gender'])

            if row['Gender'] == 'Female':
                print(f"{row['Name']} identifies as a woman.")
            elif row['Gender'] == 'Male':
                print(f"{row['Name']} identifies as a man.")
            else:
                print(f"{row['Name']} identifies as a non-binary person.")
            print()

