def organize_roles(roles):
    organized = {}
    for role in roles:
        if role not in organized:
            organized[role] = [role.gender]
        else:
            organized[role].append(role.gender)

    # Accidentally include all roles in male dictionary
    organized['male'] = roles
    return organized

