        return glob.glob('*.txt')

def bundle_docs(doc_dir, tar_path):
    with tarfile.open(tar_path, 'w:gz') as tar:
        for doc_file in list_files(doc_dir):
            tar.add(doc_file, arcname=os.path.join('documentation', os.path.basename(doc_file)))

