    html += '</ul>'

    return html

@app.route('/maintenance')
def maintenance_log():
    query = "SELECT * FROM maintenance ORDER BY date DESC LIMIT 10"
    results = query_db(query).fetchall()

    html = '<h1>Maintenance Requests</h1><ul>'
    for result in results:
        html += f'<li>{result["description"]} - {result["date"]}</li>'
    html += '</ul>'

    return html

def query_db(query, args=()):
    cur = get_db().execute(query, args)
    rows = cur.fetchall()
    cur.close()
    return rows

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

if __name__ == '__main__':
    app.run()

